insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000401', 'home', 'published', '{"title":"Home","seoTitle":"everafter.memoir — Wedding content creator","seoDescription":"Wedding content creation, reels and little films by everafter.memoir. Honest moments, fleeting details and the beautiful in-between.","ms":{"title":"Utama","seoTitle":"everafter.memoir — Wedding content creator","seoDescription":"Wedding content creator di Malaysia. Reels, gambar dan video pendek dari majlis kahwin korang, oleh everafter.memoir."},"sections":[{"key":"hero","type":"hero","visible":true,"layout":"reel","slides":[{"id":"00000000-0000-4000-8000-000000000040","url":"/brand/hero-just-married.mp4","type":"video","alt":"Newlyweds in white, soft light around them","width":720,"height":1280,"poster":"/brand/hero-just-married-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},{"id":"00000000-0000-4000-8000-000000000041","url":"/brand/hero-holding-hands.mp4","type":"video","alt":"The couple’s hands, lace and henna","width":720,"height":1280,"poster":"/brand/hero-holding-hands-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000001","url":"/brand/bride-salam.jpg","type":"image","alt":"Bride smiling as the groom rests his hand on her head after the akad nikah","width":1140,"height":1215,"poster":null,"isSample":false}],"interval":5,"eyebrow":"Wedding content creators","headline":"Your day,\n*as it felt.*","body":"Honest moments, fleeting details, and the beautiful in-between — thoughtfully captured, so you can relive the feeling long after the day has passed.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"video":null,"focal":"50% 35%","overlay":0.15,"primary":{"label":"Check your date","href":"/contact#book"},"secondary":{"label":"Watch our reels","href":"#reels"},"showTimecode":false,"ms":{"eyebrow":"Wedding content creator","headline":"Hari bahagia korang,\n*kami simpan rasanya.*","body":"Gelak tawa, air mata, renungan curi-curi masa akad. Semua momen kecil tu kami rakam, supaya korang boleh rasa balik bila-bila masa.","primary.label":"Check tarikh","secondary.label":"Tengok reels kami"}},{"key":"philosophy","type":"philosophy","visible":true,"eyebrow":"What we keep","headline":"Not just how it looked.\n*But how it felt.*","body":"The nervous laughter. The trembling hands. The little glances no one else noticed. We capture the moments that happen between the moments — the ones that make your story entirely yours.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/brand/rings-henna.jpg","type":"image","alt":"The couple’s hands with wedding rings and floral henna","width":1169,"height":1215,"poster":null,"isSample":false},"imageSide":"left","ms":{"eyebrow":"Apa yang kami kejar","headline":"Bukan sekadar cantik.\n*Tapi rasa dia sampai.*","body":"Tangan yang menggigil masa lafaz akad. Mak yang curi-curi lap air mata. Kawan-kawan yang tak berhenti mengusik. Benda-benda kecil macam ni la yang kami cari, sebab ni la yang korang akan rindu nanti."}},{"key":"reels","type":"films","visible":true,"eyebrow":"Reels","headline":"Little films.\n*Lasting feelings.*","body":"Your day unfolds in a thousand little moments. We bring them together in a way that lets you feel it all over again.","film":null,"poster":null,"filmCaption":"","reels":[{"video":{"id":"00000000-0000-4000-8000-000000000042","url":"/brand/just-married.mp4","type":"video","alt":"Bride and groom raise their hands together after the ceremony","width":720,"height":1280,"poster":"/brand/just-married-poster.jpg","isSample":false},"poster":null,"caption":"Just married"},{"video":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand/getting-ready-poster.jpg","isSample":false},"poster":null,"caption":"Getting ready"},{"video":{"id":"00000000-0000-4000-8000-000000000044","url":"/brand/bridesmaids.mp4","type":"video","alt":"Bridesmaids in powder blue laughing with the bride","width":720,"height":1280,"poster":"/brand/bridesmaids-poster.jpg","isSample":false},"poster":null,"caption":"The bridesmaids"},{"video":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"poster":null,"caption":"On the pelamin"},{"video":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"poster":null,"caption":"Cutting the cake"},{"video":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"poster":null,"caption":"Hold on a little longer"},{"video":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"poster":null,"caption":"Before the guests arrive"},{"video":{"id":"00000000-0000-4000-8000-000000000050","url":"/brand/venue-vendors.mp4","type":"video","alt":"A garden venue and its vendors","width":720,"height":1280,"poster":"/brand/venue-vendors-poster.jpg","isSample":false},"poster":null,"caption":"The venue & vendors"},{"video":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"poster":null,"caption":"Little details"}],"ms":{"headline":"Video pendek.\n*Kenangan panjang.*","body":"Satu hari, beribu momen kecil. Kami cantumkan jadi video yang buat korang senyum setiap kali tengok.","reels.0.caption":"Sah!","reels.1.caption":"Bersiap","reels.2.caption":"Geng pengapit","reels.3.caption":"Atas pelamin","reels.4.caption":"Potong kek","reels.5.caption":"Pegang erat-erat","reels.6.caption":"Sebelum tetamu sampai","reels.7.caption":"Venue & vendor","reels.8.caption":"Detail kecil"}},{"key":"featured","type":"featured_stories","visible":true,"eyebrow":"Stories","headline":"Days, *remembered.*","body":"A few wedding stories, told the way they felt.","storyIds":[],"link":{"label":"See every story","href":"/stories"},"ms":{"eyebrow":"Kisah","headline":"Majlis yang *kami sempat rakam.*","body":"Antara majlis yang kami rakam, dan cerita di sebaliknya.","link.label":"Tengok semua kisah"}},{"key":"break","type":"image_break","visible":true,"media":{"id":"00000000-0000-4000-8000-000000000003","url":"/brand/holding-hands.jpg","type":"image","alt":"Bride and groom in white holding hands, bouquet of pink flowers","width":882,"height":1181,"poster":null,"isSample":false},"focal":"50% 50%","quote":"Hold on\n*a little longer.*","caption":"","ms":{"quote":"Pegang\n*lama sikit.*"}},{"key":"services","type":"services_preview","visible":true,"eyebrow":"What we offer","headline":"Ways we can *tell your day.*","link":{"label":"View services","href":"/services"},"ms":{"eyebrow":"Servis","headline":"Apa yang *kami boleh buat.*","link.label":"Tengok servis"}},{"key":"testimonials","type":"testimonials","visible":false,"eyebrow":"Kind words","headline":"From our couples","manifesto":"We believe in unposed laughter, in the hush before the vows, in hands that hold on a little longer. We believe the best part of your day is the part you were too busy living to notice.","ms":{"eyebrow":"Kata mereka","headline":"Dari pasangan kami","manifesto":"Kami suka gelak yang tak dibuat-buat, sunyi sekejap sebelum akad, dan tangan yang pegang lama sikit. Selalunya momen paling best hari tu adalah momen yang korang sendiri tak sempat perasan."}},{"key":"social","type":"social","visible":true,"eyebrow":"Follow along","headline":"@everafter.memoir","body":"Behind the scenes, little reels and the moments in between — on Instagram and TikTok.","ms":{"eyebrow":"Follow kami","body":"Behind the scenes, reels dan momen-momen kecil. Semua ada kat Instagram dan TikTok."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"See which dates are still open, then say hello on WhatsApp.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Jom simpan\n*kenangan korang.*","body":"Check tarikh yang masih kosong, lepas tu terus WhatsApp kami.","link.label":"Check tarikh"}}]}'::jsonb, '{"title":"Home","seoTitle":"everafter.memoir — Wedding content creator","seoDescription":"Wedding content creation, reels and little films by everafter.memoir. Honest moments, fleeting details and the beautiful in-between.","ms":{"title":"Utama","seoTitle":"everafter.memoir — Wedding content creator","seoDescription":"Wedding content creator di Malaysia. Reels, gambar dan video pendek dari majlis kahwin korang, oleh everafter.memoir."},"sections":[{"key":"hero","type":"hero","visible":true,"layout":"reel","slides":[{"id":"00000000-0000-4000-8000-000000000040","url":"/brand/hero-just-married.mp4","type":"video","alt":"Newlyweds in white, soft light around them","width":720,"height":1280,"poster":"/brand/hero-just-married-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},{"id":"00000000-0000-4000-8000-000000000041","url":"/brand/hero-holding-hands.mp4","type":"video","alt":"The couple’s hands, lace and henna","width":720,"height":1280,"poster":"/brand/hero-holding-hands-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000001","url":"/brand/bride-salam.jpg","type":"image","alt":"Bride smiling as the groom rests his hand on her head after the akad nikah","width":1140,"height":1215,"poster":null,"isSample":false}],"interval":5,"eyebrow":"Wedding content creators","headline":"Your day,\n*as it felt.*","body":"Honest moments, fleeting details, and the beautiful in-between — thoughtfully captured, so you can relive the feeling long after the day has passed.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"video":null,"focal":"50% 35%","overlay":0.15,"primary":{"label":"Check your date","href":"/contact#book"},"secondary":{"label":"Watch our reels","href":"#reels"},"showTimecode":false,"ms":{"eyebrow":"Wedding content creator","headline":"Hari bahagia korang,\n*kami simpan rasanya.*","body":"Gelak tawa, air mata, renungan curi-curi masa akad. Semua momen kecil tu kami rakam, supaya korang boleh rasa balik bila-bila masa.","primary.label":"Check tarikh","secondary.label":"Tengok reels kami"}},{"key":"philosophy","type":"philosophy","visible":true,"eyebrow":"What we keep","headline":"Not just how it looked.\n*But how it felt.*","body":"The nervous laughter. The trembling hands. The little glances no one else noticed. We capture the moments that happen between the moments — the ones that make your story entirely yours.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/bran