tting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"poster":null,"caption":"Cutting the cake"},{"video":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"poster":null,"caption":"Hold on a little longer"},{"video":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"poster":null,"caption":"Before the guests arrive"},{"video":{"id":"00000000-0000-4000-8000-000000000050","url":"/brand/venue-vendors.mp4","type":"video","alt":"A garden venue and its vendors","width":720,"height":1280,"poster":"/brand/venue-vendors-poster.jpg","isSample":false},"poster":null,"caption":"The venue & vendors"},{"video":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"poster":null,"caption":"Little details"}],"ms":{"headline":"Video pendek.\n*Kenangan panjang.*","body":"Satu hari, beribu momen kecil. Kami cantumkan jadi video yang buat korang senyum setiap kali tengok.","reels.0.caption":"Sah!","reels.1.caption":"Bersiap","reels.2.caption":"Geng pengapit","reels.3.caption":"Atas pelamin","reels.4.caption":"Potong kek","reels.5.caption":"Pegang erat-erat","reels.6.caption":"Sebelum tetamu sampai","reels.7.caption":"Venue & vendor","reels.8.caption":"Detail kecil"}},{"key":"featured","type":"featured_stories","visible":true,"eyebrow":"Stories","headline":"Days, *remembered.*","body":"A few wedding stories, told the way they felt.","storyIds":[],"link":{"label":"See every story","href":"/stories"},"ms":{"eyebrow":"Kisah","headline":"Majlis yang *kami sempat rakam.*","body":"Antara majlis yang kami rakam, dan cerita di sebaliknya.","link.label":"Tengok semua kisah"}},{"key":"break","type":"image_break","visible":true,"media":{"id":"00000000-0000-4000-8000-000000000003","url":"/brand/holding-hands.jpg","type":"image","alt":"Bride and groom in white holding hands, bouquet of pink flowers","width":882,"height":1181,"poster":null,"isSample":false},"focal":"50% 50%","quote":"Hold on\n*a little longer.*","caption":"","ms":{"quote":"Pegang\n*lama sikit.*"}},{"key":"services","type":"services_preview","visible":true,"eyebrow":"What we offer","headline":"Ways we can *tell your day.*","link":{"label":"View services","href":"/services"},"ms":{"eyebrow":"Servis","headline":"Apa yang *kami boleh buat.*","link.label":"Tengok servis"}},{"key":"testimonials","type":"testimonials","visible":false,"eyebrow":"Kind words","headline":"From our couples","manifesto":"We believe in unposed laughter, in the hush before the vows, in hands that hold on a little longer. We believe the best part of your day is the part you were too busy living to notice.","ms":{"eyebrow":"Kata mereka","headline":"Dari pasangan kami","manifesto":"Kami suka gelak yang tak dibuat-buat, sunyi sekejap sebelum akad, dan tangan yang pegang lama sikit. Selalunya momen paling best hari tu adalah momen yang korang sendiri tak sempat perasan."}},{"key":"social","type":"social","visible":true,"eyebrow":"Follow along","headline":"@everafter.memoir","body":"Behind the scenes, little reels and the moments in between — on Instagram and TikTok.","ms":{"eyebrow":"Follow kami","body":"Behind the scenes, reels dan momen-momen kecil. Semua ada kat Instagram dan TikTok."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"See which dates are still open, then say hello on WhatsApp.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Jom simpan\n*kenangan korang.*","body":"Check tarikh yang masih kosong, lepas tu terus WhatsApp kami.","link.label":"Check tarikh"}}]}'::jsonb, now(), 0) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000402', 'stories', 'published', '{"title":"Stories","seoTitle":"Stories — everafter.memoir","seoDescription":"Wedding stories by everafter.memoir — candid moments, quiet details and little films.","ms":{"title":"Kisah","seoTitle":"Kisah — everafter.memoir","seoDescription":"Majlis-majlis yang kami rakam: momen spontan, detail kecil dan video pendek."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":{"id":"00000000-0000-4000-8000-000000000018","url":"/brand/engagement-sign.jpg","type":"image","alt":"Engagement welcome sign on a wooden easel between vases of flowers","width":1600,"height":2133,"poster":null,"isSample":false},"ms":{"eyebrow":"Kisah kami","headline":"Setiap majlis\n*ada rasa sendiri.*","body":"Ada yang meriah sampai malam, ada yang kecil dan intim. Ni antara majlis yang kami sempat rakam."}},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"See which dates are still open.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Lepas ni,\n*kisah korang pula.*","body":"Tengok tarikh yang masih kosong.","link.label":"Check tarikh"}}]}'::jsonb, '{"title":"Stories","seoTitle":"Stories — everafter.memoir","seoDescription":"Wedding stories by everafter.memoir — candid moments, quiet details and little films.","ms":{"title":"Kisah","seoTitle":"Kisah — everafter.memoir","seoDescription":"Majlis-majlis yang kami rakam: momen spontan, detail kecil dan video pendek."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Our stories","headline":"Every wedding\n*feels d