insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000403', 'services', 'published', '{"title":"Services","seoTitle":"Services — everafter.memoir","seoDescription":"Wedding content creator (WCC) coverage, highlight films and personalised coverage by everafter.memoir.","ms":{"title":"Servis","seoTitle":"Servis — everafter.memoir","seoDescription":"Servis wedding content creator (WCC), video highlight dan liputan ikut citarasa oleh everafter.memoir."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"eyebrow":"Servis","headline":"Ikut cara\n*korang nak.*","body":"Setiap pasangan nak simpan benda yang lain-lain. Bagitahu kami apa yang paling penting, kami susun liputan ikut tu."}},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Pick your date and we will reply with options for your day.","ms":{"addonsHeadline":"Tambahan","footnote":"Setiap majlis lain-lain, jadi harga pun ikut majlis. Pilih tarikh dulu, nanti kami bagi pilihan yang sesuai."}},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Tak pasti\n*nak ambil yang mana?*","body":"Cerita sikit pasal majlis korang, kami tolong pilihkan.","link.label":"Check tarikh"}}]}'::jsonb, '{"title":"Services","seoTitle":"Services — everafter.memoir","seoDescription":"Wedding content creator (WCC) coverage, highlight films and personalised coverage by everafter.memoir.","ms":{"title":"Servis","seoTitle":"Servis — everafter.memoir","seoDescription":"Servis wedding content creator (WCC), video highlight dan liputan ikut citarasa oleh everafter.memoir."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"eyebrow":"Servis","headline":"Ikut cara\n*korang nak.*","body":"Setiap pasangan nak simpan benda yang lain-lain. Bagitahu kami apa yang paling penting, kami susun liputan ikut tu."}},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Pick your date and we will reply with options for your day.","ms":{"addonsHeadline":"Tambahan","footnote":"Setiap majlis lain-lain, jadi harga pun ikut majlis. Pilih tarikh dulu, nanti kami bagi pilihan yang sesuai."}},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Tak pasti\n*nak ambil yang mana?*","body":"Cerita sikit pasal majlis korang, kami tolong pilihkan.","link.label":"Check tarikh"}}]}'::jsonb, now(), 2) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000404', 'about', 'published', '{"title":"About","seoTitle":"About — everafter.memoir","seoDescription":"everafter.memoir is a team of two wedding content creators, made for the moments that deserve to be remembered beyond the photographs.","ms":{"title":"Tentang Kami","seoTitle":"Tentang Kami — everafter.memoir","seoDescription":"everafter.memoir, team dua orang wedding content creator yang rakam momen-momen kecil hari bahagia korang."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"About","headline":"Behind every memoir,\n*a thousand little feelings.*","body":"everafter.memoir was created for the moments that deserve to be remembered beyond the photographs — the laughter, the happy tears, the quiet glances, and all the beautiful in-between.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"ms":{"eyebrow":"Tentang kami","headline":"Setiap memoir,\n*ada seribu rasa.*","body":"everafter.memoir bermula sebab kami percaya majlis kahwin bukan sekadar gambar cantik. Ia pasal gelak tawa, air mata gembira, renungan senyap, dan semua benda kecil di celah-celahnya."}},{"key":"team","type":"team","visible":true,"eyebrow":"The team","headline":"Two creators,\n*one way of seeing.*","body":"We are a team of two — wedding content creators first, photographers too. One of us is usually where the laughter is; the other is watching for the moment just after it.","members":[{"name":"","role":"Wedding content creator","bio":"","photo":null},{"name":"","role":"Wedding content creator & photographer","bio":"","photo":null}],"ms":{"eyebrow":"Kami berdua","headline":"Dua orang,\n*satu cara pandang.*","body":"Kami team dua orang. Wedding content creator, dan photographer sekali. Selalunya sorang ada dekat tempat orang tengah gelak, sorang lagi tunggu momen lepas tu.","members.0.role":"Wedding content creator","members.1.role":"Wedding content creator & photographer"}},{"key":"approach","type":"text_image","visible":true,"eyebrow":"How we work","headline":"Close enough to feel it.\n*Quiet enough to miss nothing.*","body":"We stay near the moments that matter and out of the way of the ones that should simply happen.\n\nThe result is content that feels like being there again — the getting ready, the vows, the people you love, and everything in between.","media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"imageSide":"right","ms":{"eyebrow":"Cara kami kerja","headline":"Cukup dekat untuk rasa.\n*Cukup senyap untuk tak terlepas apa-apa.*","body":"Kami duduk dekat dengan momen yang penting, dan tak kacau momen yang patut berlaku dengan sendiri.\n\nHasilnya, video dan gambar yang buat korang rasa macam berada kat situ semula. Masa bersiap, masa akad, orang-orang tersayang, dan semua yang ada di celah-celahnya."}},{"key":"collage","type":"collage","visible":true,"eyebrow":"In between","headline":"The moments\n*no one planned.*","body":"A kiss on the hand. A laugh on the pelamin. The rings, finally where they belong.","items":[{"media":{"id":"00000000-0000-4000-8000-000000000007","url":"/brand/salam-closeup.jpg","type":"image","alt":"Bride kissing the groom’s hand, eyes closed","width":424,"height":532,"poster":null,"isSample":false},"caption":"Salam"},{"media":{"id":"00000000-0000-4000-8000-000000000009","url":"/brand/pelamin-laugh.jpg","type":"image","alt":"Groom and bride sharing a laugh on the pelamin","width":424,"height":533,"poster":null,"isSample":false},"caption":""},{"media":{"id":"00000000-0000-4000-8000-000000000005","url":"/brand/bride-smile.jpg","type":"image","alt":"Bride in a tiara and veil smiling","width":462,"height":1089,"poster":null,"isSample":false},"caption":""},{"media":{"id":"00000000-0000-4000-8000-000000000010","url":"/brand/rings-detail.jpg","type":"image","alt":"Close-up of the rings and henna","width":423,"height":533,"poster":null,"isSample":false},"caption":"Forever, on one finger"},{"media":{"id":"00000000-0000-4000-8000-000000000008","url":"/brand/pelamin-wide.jpg","type":"image","alt":"Couple seated on the pelamin surrounded by white flowers","width":423,"height":532,"poster":null,"isSample":false},"caption":""}],"link":{"label":"See the stories","href":"/stories"},"ms":{"eyebrow":"Di celah-celah","headline":"Momen yang\n*tak dirancang.*","body":"Cium tangan. Gelak atas pelamin. Cincin yang akhirnya tersarung.","items.0.caption":"Salam","items.3.caption":"Satu jari, selamanya","link.label":"Tengok kisah"}},{"key":"founder","type":"founder","visible":false,"eyebrow":"The person behind the camera","headline":"Hello, *I am…*","name":"","role":"","body":"","media":null},{"key":"quote","type":"quote","visible":true,"text":"Your day, as it felt — not just as it looked.","ms":{"text":"Bukan sekadar cantik dalam gambar. Tapi rasa dia masih sampai."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"We would love to hear about your day.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Jom simpan\n*kenangan korang.*","body":"Kami nak sangat dengar pasal majlis korang.","link.label":"Check tarikh"}}]}'::jsonb, '{"title":"About","seoTitle":"About — everafter.memoir","seoDescription":"everafter.memoir is a team of two wedding content creators, made for the moments that deserve to be remembered beyond the photographs.","ms":{"title":"Tentang Kami","seoTitle":"Tentang Kami — everafter.memoir","seoDescription":"everafter.memoir, team dua orang wedding content creator yang rakam momen-momen kecil hari bahagia korang."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"About","headline":"Behind every memoir,\n*a thousand little feelings.*","body":"everafter.memoir was created for the moments that deserve to be remembered beyond the photographs — the laughter, the happy tears, the quiet glances, and all the beautiful in-between.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"ms":{"eyebrow":"Tentang kami","headline":"Setiap memoir,\n*ada seribu rasa.*","body":"everafter.memoir bermula sebab kami percaya majlis kahwin bukan sekadar gambar cantik. Ia pasal gelak tawa, air mata gembira, renungan senyap, dan semua benda kecil di celah-celahnya."}},{"key":"team","type":"team","visible":true,"eyebrow":"The team","headline":"Two creators,\n*one way of seeing.*","body":"We are a team of two — wedding content creators first, photographers too. One of us is usually where the laughter is; the other is watching for the moment just after it.","members":[{"name":"","role":"Wedding content creator","bio":"","photo":null},{"name":"","role":"Wedding content creator & photographer","bio":"","photo":null}],"ms":{"eyebrow":"Kami berdua","headline":"Dua orang,\n*satu cara pandang.*","body":"Kami team dua orang. Wedding content creator, dan photographer sekali. Selalunya sorang ada dekat tempat orang tengah gelak, sorang lagi tunggu momen lepas tu.","members.0.role":"Wedding content creator","members.1.role":"Wedding content creator & photographer"}},{"key":"approach","type":"text_image","visible":true,"eyebrow":"How we work","headline":"Close enough to feel it.\n*Quiet enough to miss nothing.*","body":"We stay near the moments that matter and out of the way of the ones that should simply happen.\n\nThe result is content that feels like being there again — the getting ready, the vows, the people you love, and everything in between.","media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"imageSide":"right","ms":{"eyebrow":"Cara kami kerja","headline":"Cukup dekat untuk rasa.\n*Cukup senyap untuk tak terlepas apa-apa.*","body":"Kami duduk dekat dengan momen yang penting, dan tak kacau momen yang patut berlaku dengan sendiri.\n\nHasilnya, video dan gambar yang buat korang rasa macam berada kat situ semula. Masa bersiap, masa akad, orang-orang tersayang, dan semua yang ada di celah-celahnya."}},{"key":"collage","type":"collage","visible":true,"eyebrow":"In between","headline":"The moments\n*no one planned.*","body":"A kiss on the hand. A laugh on the pelamin. The rings, finally where they belong.","items":[{"media":{"id":"00000000-0000-4000-8000-000000000007","url":"/brand/salam-closeup.jpg","type":"image","alt":"Bride kissing the groom’s hand, eyes closed","width":424,"height":532,"poster":null,"isSample":false},"caption":"Salam"},{"media":{"id":"00000000-0000-4000-8000-000000000009","url":"/brand/pelamin-laugh.jpg","type":"image","alt":"Groom and bride sharing a laugh on the pelamin","width":424,"height":533,"poster":null,"isSample":false},"caption":""},{"media":{"id":"00000000-0000-4000-8000-000000000005","url":"/brand/bride-smile.jpg","type":"image","alt":"Bride in a tiara and veil smiling","width":462,"height":1089,"poster":null,"isSample":false},"caption":""},{"media":{"id":"00000000-0000-4000-8000-000000000010","url":"/brand/rings-detail.jpg","type":"image","alt":"Close-up of the rings and henna","width":423,"height":533,"poster":null,"isSample":false},"caption":"Forever, on one finger"},{"media":{"id":"00000000-0000-4000-8000-000000000008","url":"/brand/pelamin-wide.jpg","type":"image","alt":"Couple seated on the pelamin surrounded by white flowers","width":423,"height":532,"poster":null,"isSample":false},"caption":""}],"link":{"label":"See the stories","href":"/stories"},"ms":{"eyebrow":"Di celah-celah","headline":"Momen yang\n*tak dirancang.*","body":"Cium tangan. Gelak atas pelamin. Cincin yang akhirnya tersarung.","items.0.caption":"Salam","items.3.caption":"Satu jari, selamanya","link.label":"Tengok kisah"}},{"key":"founder","type":"founder","visible":false,"eyebrow":"The person behind the camera","headline":"Hello, *I am…*","name":"","role":"","body":"","media":null},{"key":"quote","type":"quote","visible":true,"text":"Your day, as it felt — not just as it looked.","ms":{"text":"Bukan sekadar cantik dalam gambar. Tapi rasa dia masih sampai."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"We would love to hear about your day.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Jom simpan\n*kenangan korang.*","body":"Kami nak sangat dengar pasal majlis korang.","link.label":"Check tarikh"}}]}'::jsonb, now(), 3) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000405', 'contact', 'published', '{"title":"Contact","seoTitle":"Book your date — everafter.memoir","seoDescription":"Check which wedding dates are still available with everafter.memoir, then book on WhatsApp.","ms":{"title":"Hubungi","seoTitle":"Book tarikh — everafter.memoir","seoDescription":"Check tarikh yang masih kosong dengan everafter.memoir, pilih slot siang atau malam, lepas tu book terus kat WhatsApp."},"sections":[{"key":"book","type":"booking","visible":true,"eyebrow":"Book your date","headline":"Is your date\n*still free?*","body":"Pick your date and a day or night slot, add a few details, and we’ll continue on WhatsApp.","note":"Each date has two slots: day and night. Your date is confirmed once we reply.","ms":{"eyebrow":"Booking","headline":"Tarikh korang\n*masih kosong?*","body":"Pilih tarikh, pilih slot siang atau malam, isi sikit info. Lepas tu kita sambung borak kat WhatsApp.","note":"Satu hari ada dua slot: siang dan malam. Tarikh confirm lepas kami reply."}},{"key":"inquiry","type":"inquiry","visible":true,"headline":"Prefer email?\n*Send a detailed inquiry.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them.","ms":{"headline":"Lebih selesa emel?\n*Hantar pertanyaan.*","body":"Cerita sikit pasal majlis korang, plan korang, dan momen yang korang paling nak simpan.","successHeadline":"Terima kasih! *Mesej korang dah sampai.*","successBody":"Kami baca semua pertanyaan sendiri, dan akan reply ke emel yang korang bagi.","privacyNote":"Info ni kami guna untuk reply dan rancang liputan je. Kami tak jual atau kongsi dengan sesiapa."}}]}'::jsonb, '{"title":"Contact","seoTitle":"Book your date — everafter.memoir","seoDescription":"Check which wedding dates are still available with everafter.memoir, then book on WhatsApp.","ms":{"title":"Hubungi","seoTitle":"Book tarikh — everafter.memoir","seoDescription":"Check tarikh yang masih kosong dengan everafter.memoir, pilih slot siang atau malam, lepas tu book terus kat WhatsApp."},"sections":[{"key":"book","type":"booking","visible":true,"eyebrow":"Book your date","headline":"Is your date\n*still free?*","body":"Pick your date and a day or night slot, add a few details, and we’ll continue on WhatsApp.","note":"Each date has two slots: day and night. Your date is confirmed once we reply.","ms":{"eyebrow":"Booking","headline":"Tarikh korang\n*masih kosong?*","body":"Pilih tarikh, pilih slot siang atau malam, isi sikit info. Lepas tu kita sambung borak kat WhatsApp.","note":"Satu hari ada dua slot: siang dan malam. Tarikh confirm lepas kami reply."}},{"key":"inquiry","type":"inquiry","visible":true,"headline":"Prefer email?\n*Send a detailed inquiry.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them.","ms":{"headline":"Lebih selesa emel?\n*Hantar pertanyaan.*","body":"Cerita sikit pasal majlis korang, plan korang, dan momen yang korang paling nak simpan.","successHeadline":"Terima kasih! *Mesej korang dah sampai.*","successBody":"Kami baca semua pertanyaan sendiri, dan akan reply ke emel yang korang bagi.","privacyNote":"Info ni kami guna untuk reply dan rancang liputan je. Kami tak jual atau kongsi dengan sesiapa."}}]}'::jsonb, now(), 4) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000406', 'privacy', 'published', '{"title":"Privacy","seoTitle":"Privacy policy — everafter.memoir","seoDescription":"How everafter.memoir handles the personal details you share with us.","ms":{"title":"Privasi","seoTitle":"Dasar privasi — everafter.memoir","seoDescription":"Macam mana everafter.memoir jaga info peribadi yang korang kongsi dengan kami."},"sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you book a date or send an inquiry, we receive the details you type in: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding. When you book through WhatsApp, the conversation continues in WhatsApp under its own privacy terms.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the everafter.memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any message from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies.","ms":{"headline":"Dasar privasi","body":"## Apa yang kami kumpul\n\nApabila anda menempah tarikh atau menghantar pertanyaan, kami menerima maklumat yang anda isi: nama anda, nama pasangan, emel, nombor WhatsApp, tarikh majlis, lokasi, jenis majlis, servis yang diminati, bajet (pilihan) dan sebarang nota.\n\n## Mengapa kami mengumpulnya\n\nKami menggunakan maklumat ini hanya untuk membalas anda, menyediakan sebut harga dan merancang liputan majlis anda. Apabila anda menempah melalui WhatsApp, perbualan diteruskan di WhatsApp di bawah terma privasinya sendiri.\n\n## Siapa yang boleh melihatnya\n\nPertanyaan anda disimpan dengan selamat dan hanya boleh dilihat oleh pasukan everafter.memoir. Kami tidak menjual, menyewa atau berkongsi maklumat anda dengan sesiapa untuk tujuan pemasaran.\n\n## Berapa lama kami menyimpannya\n\nKami menyimpan pertanyaan selama yang diperlukan untuk bekerja dengan anda, dan memadam pertanyaan yang telah selesai apabila tidak diperlukan lagi.\n\n## Pilihan anda\n\nAnda boleh meminta pada bila-bila masa untuk melihat, membetulkan atau memadam maklumat yang anda hantar. Balas mana-mana mesej daripada kami atau hantar pertanyaan baharu dengan permintaan anda.\n\n## Kuki\n\nWebsite ini tidak menggunakan kuki pengiklanan atau penjejakan."}}]}'::jsonb, '{"title":"Privacy","seoTitle":"Privacy policy — everafter.memoir","seoDescription":"How everafter.memoir handles the personal details you share with us.","ms":{"title":"Privasi","seoTitle":"Dasar privasi — everafter.memoir","seoDescription":"Macam mana everafter.memoir jaga info peribadi yang korang kongsi dengan kami."},"sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you book a date or send an inquiry, we receive the details you type in: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding. When you book through WhatsApp, the conversation continues in WhatsApp under its own privacy terms.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the everafter.memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any message from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies.","ms":{"headline":"Dasar privasi","body":"## Apa yang kami kumpul\n\nApabila anda menempah tarikh atau menghantar pertanyaan, kami menerima maklumat yang anda isi: nama anda, nama pasangan, emel, nombor WhatsApp, tarikh majlis, lokasi, jenis majlis, servis yang diminati, bajet (pilihan) dan sebarang nota.\n\n## Mengapa kami mengumpulnya\n\nKami menggunakan maklumat ini hanya untuk membalas anda, menyediakan sebut harga dan merancang liputan majlis anda. Apabila anda menempah melalui WhatsApp, perbualan diteruskan di WhatsApp di bawah terma privasinya sendiri.\n\n## Siapa yang boleh melihatnya\n\nPertanyaan anda disimpan dengan selamat dan hanya boleh dilihat oleh pasukan everafter.memoir. Kami tidak menjual, menyewa atau berkongsi maklumat anda dengan sesiapa untuk tujuan pemasaran.\n\n## Berapa lama kami menyimpannya\n\nKami menyimpan pertanyaan selama yang diperlukan untuk bekerja dengan anda, dan memadam pertanyaan yang telah selesai apabila tidak diperlukan lagi.\n\n## Pilihan anda\n\nAnda boleh meminta pada bila-bila masa untuk melihat, membetulkan atau memadam maklumat yang anda hantar. Balas mana-mana mesej daripada kami atau hantar pertanyaan baharu dengan permintaan anda.\n\n## Kuki\n\nWebsite ini tidak menggunakan kuki pengiklanan atau penjejakan."}}]}'::jsonb, now(), 5) on conflict (slug) do nothing;
