insert into public.stories (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000102', 'published', '{"title":"The Quiet Between Us","slug":"the-quiet-between-us","excerpt":"White flowers, soft light and a kiss on the hand.","description":"A soft morning and a small room full of white flowers. Between the vows and the first photos there was a moment of quiet — a hand on her head, a kiss on his — and that is the part we wanted to keep.","cover":{"id":"00000000-0000-4000-8000-000000000001","url":"/brand/bride-salam.jpg","type":"image","alt":"Bride smiling as the groom rests his hand on her head after the akad nikah","width":1140,"height":1215,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Akad nikah","Pelamin"],"featured":true,"gallery":[{"media":null,"caption":"The akad","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000007","url":"/brand/salam-closeup.jpg","type":"image","alt":"Bride kissing the groom’s hand, eyes closed","width":424,"height":532,"poster":null,"isSample":false},"caption":"Salam.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000008","url":"/brand/pelamin-wide.jpg","type":"image","alt":"Couple seated on the pelamin surrounded by white flowers","width":423,"height":532,"poster":null,"isSample":false},"caption":"","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"caption":"Hold on a little longer.","layout":"offset"},{"media":null,"caption":"The little things","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000010","url":"/brand/rings-detail.jpg","type":"image","alt":"Close-up of the rings and henna","width":423,"height":533,"poster":null,"isSample":false},"caption":"","layout":"half"},{"media":{"id":"00000000-0