insert into public.stories (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000101', 'published', '{"title":"A Day to Remember","slug":"a-day-to-remember","excerpt":"Bright walls, white baju and a house full of the people who matter.","description":"Getting ready at home, bridesmaids in powder blue and a family that would not stop laughing. A day that was loud in the best way.","cover":{"id":"00000000-0000-4000-8000-000000000004","url":"/brand/family-portrait.jpg","type":"image","alt":"Family in white baju Melayu and wedding dresses laughing together","width":853,"height":1223,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Akad nikah","At home"],"featured":true,"gallery":[{"media":null,"caption":"Before","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand/getting-ready-poster.jpg","isSample":false},"caption":"Getting ready.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000005","url":"/brand/bride-smile.jpg","type":"image","alt":"Bride in a tiara and veil smiling","width":462,"height":1089,"poster":null,"isSample":false},"caption":"Ready.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000044","url":"/brand/bridesmaids.mp4","type":"video","alt":"Bridesmaids in powder blue laughing with the bride","width":720,"height":1280,"poster":"/brand/bridesmaids-poster.jpg","isSample":false},"caption":"The bridesmaids.","layout":"offset"},{"media":null,"caption":"Everyone","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000004","url":"/brand/family-portrait.jpg","type":"image","alt":"Family in white baju Melayu and wedding dresses laughing together","width":853,"height":1223,"poster":null,"isSample":false},"caption":"The whole family, finally in one photo.","layout":"offset"},{"media":{"id":"00000000-0000-4000-8000-000000000006","url":"/brand/couple-standing.jpg","type":"image","alt":"Newlyweds standing together and smiling","width":441,"height":1088,"poster":null,"isSample":false},"caption":"","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000042","url":"/brand/just-married.mp4","type":"video","alt":"Bride and groom raise their hands together after the ceremony","width":720,"height":1280,"poster":"/brand/just-married-poster.jpg","isSample":false},"caption":"Just married.","layout":"half"}],"seoTitle":"","seoDescription":"","isSample":true,"ms":{"title":"Hari Untuk Dikenang","excerpt":"Dinding kuning ceria, baju putih, dan rumah penuh orang tersayang.","description":"Bersiap kat rumah, pengapit berbaju biru lembut, dan family yang tak berhenti gelak. Riuh, tapi riuh yang best.","tags.0":"Akad nikah","tags.1":"Di rumah","gallery.0.caption":"Sebelum","gallery.1.caption":"Bersiap.","gallery.2.caption":"Dah siap.","gallery.3.caption":"Geng pengapit.","gallery.4.caption":"Semua orang","gallery.5.caption":"Satu family, akhirnya dalam satu frame.","gallery.7.caption":"Sah!"}}'::jsonb, '{"title":"A Day to Remember","slug":"a-day-to-remember","excerpt":"Bright walls, white baju and a house full of the people who matter.","description":"Getting ready at home, bridesmaids in powder blue and a family that would not stop laughing. A day that was loud in the best way.","cover":{"id":"00000000-0000-4000-8000-000000000004","url":"/brand/family-portrait.jpg","type":"image","alt":"Family in white baju Melayu and wedding dresses laughing together","width":853,"height":1223,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Akad nikah","At home"],"featured":true,"gallery":[{"media":null,"caption":"Before","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand