ion":"Semua orang","gallery.5.caption":"Satu family, akhirnya dalam satu frame.","gallery.7.caption":"Sah!"}}'::jsonb, now(), 1) on conflict (id) do nothing;
insert into public.stories (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000103', 'published', '{"title":"In Red and Bloom","slug":"in-red-and-bloom","excerpt":"Deep red drapes, crystal light and a cake cut together.","description":"A reception dressed in deep red and blush flowers. We started with the empty hall, stayed for the pelamin and left after the last slice of cake.","cover":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Reception","Pelamin"],"featured":true,"gallery":[{"media":null,"caption":"The hall","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"caption":"","layout":"full"},{"media":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"caption":"Before the doors opened.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"caption":"","layout":"half"},{"media":null,"caption":"The couple","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"caption":"On the pelamin.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"caption":"One slice, together.","layout":"half"}],"seoTitle":"","seoDescription":"","isSample":true,"ms":{"title":"Merah dan Mekar","excerpt":"Langsir merah pekat, chandelier kristal, dan kek yang dipotong sama-sama.","description":"Majlis sanding berhias merah pekat dan bunga pink. Kami mula dari dewan yang masih kosong, lepak lama kat pelamin, dan balik lepas potongan kek terakhir.","tags.0":"Sanding","tags.1":"Pelamin","gallery.0.caption":"Dewan","gallery.2.caption":"Sebelum pintu dibuka.","gallery.4.caption":"Pengantin","gallery.5.caption":"Atas pelamin.","gallery.6.caption":"Satu potong, sama-sama."}}'::jsonb, '{"title":"In Red and Bloom","slug":"in-red-and-bloom","excerpt":"Deep red drapes, crystal light and a cake cut together.","description":"A reception dressed in deep red and blush flowers. We started with the empty hall, stayed for the pelamin and left after the last slice of cake.","cover":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Reception","Pelamin"],"featured":true,"gallery":[{"media":null,"caption":"The hall","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"caption":"","layout":"full"},{"media":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"caption":"Before the doors opened.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"caption":"","layout":"half"},{"media":null,"caption":"The couple","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"caption":"On the pelamin.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"caption":"One slice, together.","layout":"half"}],"seoTitle":"","seoDescription":"","isSample":true,"ms":{"title":"Merah dan Mekar","excerpt":"Langsir merah pekat, chandelier kristal, dan kek yang dipotong sama-sama.","description":"Majlis sanding berhias merah pekat dan bunga pink. Kami mula dari dewan yang masih kosong, lepak lama kat pelamin, dan balik lepas potongan kek terakhir.","tags.0":"Sanding","tags.1":"Pelamin","gallery.0.caption":"Dewan","gallery.2.caption":"Sebelum pintu dibuka.","gallery.4.caption":"Pengantin","gallery.5.caption":"Atas pelamin.","gallery.6.caption":"Satu potong, sama-sama."}}'::jsonb, now(), 2) on conflict (id) do nothing;
insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000201', 'published', '{"kind":"service","name":"Wedding Content Creator (WCC)","summary":"Candid moments, behind-the-scenes details and the atmosphere of your celebration — as reels, photos and stories ready to share.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as short-form content you can share on the day and keep for years.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"summary":"Momen spontan, behind the scenes dan suasana majlis, siap jadi reels, gambar dan story yang terus boleh share.","description":"Kami rakam hari korang macam mana ia berlaku. Masa bersiap, momen di celah-celah, orang-orang sekeliling. Ada yang korang boleh share hari tu juga, ada yang korang simpan bertahun-tahun."}}'::jsonb, '{"kind":"service","name":"Wedding Content Creator (WCC)","summary":"Candid moments, behind-the-scenes details and the atmosphere of your celebration — as reels, photos and stories ready to share.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as short-form content you can share on the day and keep for years.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"summary":"Momen spontan, behind the scenes dan suasana majlis, siap jadi reels, gambar dan story yang terus boleh share.","description":"Kami rakam hari korang macam mana ia berlaku. Masa bersiap, momen di celah-celah, orang-orang sekeliling. Ada yang korang boleh share hari tu juga, ada yang korang simpan bertahun-tahun."}}'::jsonb, now(), 0) on conflict (id) do nothing;
insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000202', 'published', '{"kind":"service","name":"Wedding Highlight Films","summary":"Short-form storytelling that brings together the emotions, energy and memorable details of the day.","description":"A little film made from the moments that mattered most, so you can feel your day all over again.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Video Highlight","summary":"Video pendek yang himpunkan emosi, keriuhan dan detail yang korang tak nak lupa.","description":"Video kecil dari momen-momen paling bermakna, supaya korang boleh rasa hari tu sekali lagi."}}'::jsonb, '{"kind":"service","name":"Wedding Highlight Films","summary":"Short-form storytelling that brings together the emotions, energy and memorable details of the day.","description":"A little film made from the moments that mattered most, so you can feel your day all over again.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Video Highlight","summary":"Video pendek yang himpunkan emosi, keriuhan dan detail yang korang tak nak lupa.","description":"Video kecil dari momen-momen paling bermakna, supaya korang boleh rasa hari tu sekali lagi."}}'::jsonb, now(), 1) on conflict (id) do nothing;
insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000203', 'published', '{"kind":"service","name":"Personalised Coverage","summary":"Tailored content coverage based on each couple''s priorities and wedding plans.","description":"Tell us what matters to you and we will shape the coverage around it — from intimate ceremonies to full celebrations.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000065","url":"/brand/hall-decor-poster.jpg","type":"image","alt":"Reception hall aisle with white flowers","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Liputan Ikut Citarasa","summary":"Liputan yang disusun ikut apa yang paling penting untuk korang berdua.","description":"Bagitahu apa yang korang nak, kami susun liputan ikut tu. Majlis kecil pun boleh, majlis besar pun boleh."}}'::jsonb, '{"kind":"service","name":"Personalised Coverage","summary":"Tailored content coverage based on each couple''s priorities and wedding plans.","description":"Tell us what matters to you and we will shape the coverage around it — from intimate ceremonies to full celebrations.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000065","url":"/brand/hall-decor-poster.jpg","type":"image","alt":"Reception hall aisle with white flowers","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Liputan Ikut Citarasa","summary":"Liputan yang disusun ikut apa yang paling penting untuk korang berdua.","description":"Bagitahu apa yang korang nak, kami susun liputan ikut tu. Majlis kecil pun boleh, majlis besar pun boleh."}}'::jsonb, now(), 2) on conflict (id) do nothing;
